package hu.synostream.android;
import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.view.*;import android.widget.*;import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.uiautomator.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import java.util.*;import java.lang.reflect.*;import static org.junit.Assert.*;
@RunWith(AndroidJUnit4.class)
public class Android052Test {
 final Android050FlowTest flow=new Android050FlowTest();
 @After public void cleanup()throws Exception{if(flow.app!=null)flow.instrumentation.runOnMainSync(()->{flow.app.cancelScan();flow.app.epoch++;flow.app.torrentDraft.close();});flow.cleanup();}
 Object field(Object object,String name)throws Exception{Field f=object.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(object);}
 void set(Object object,String name,Object value)throws Exception{Field f=object.getClass().getDeclaredField(name);f.setAccessible(true);f.set(object,value);}
 void invoke(Object object,String name)throws Exception{Method m=object.getClass().getDeclaredMethod(name);m.setAccessible(true);m.invoke(object);}
 DownloadsUi downloads()throws Exception{MainActivity activity=flow.activity();DownloadsUi[] result={null};flow.instrumentation.runOnMainSync(()->{result[0]=new DownloadsUi(activity);activity.downloadsUi=result[0];result[0].show();});assertTrue(flow.device.wait(Until.hasObject(By.text("Fixture torrent")),10000));flow.instrumentation.runOnMainSync(()->{try{flow.app.main.removeCallbacks((Runnable)field(result[0],"poll"));}catch(Exception e){throw new RuntimeException(e);}});return result[0];}
 JSONObject task(int n)throws Exception{return new JSONObject().put("id","id"+n).put("title",String.format(java.util.Locale.ROOT,"Task %02d",n)).put("status","paused").put("size",100);}
 @Test public void refreshKeepsAdapterRowsSelectionAndScroll()throws Exception{try(FakeNas nas=new FakeNas()){flow.setup(nas,List.of());DownloadsUi ui=downloads();Object[] saved=new Object[1];int[] position=new int[2];flow.instrumentation.runOnMainSync(()->{try{ListView list=(ListView)field(ui,"tasks");List<JSONObject> rows=new ArrayList<>();for(int n=0;n<30;n++)rows.add(task(n));set(ui,"snapshot",rows);Set<String> selected=(Set<String>)field(ui,"selected");selected.add("id0");invoke(ui,"drawTasks");BaseAdapter adapter=(BaseAdapter)list.getAdapter();saved[0]=adapter;View first=adapter.getView(0,null,list),rebound=adapter.getView(1,first,list);assertSame(first,rebound);CheckBox checkbox=(CheckBox)((android.view.ViewGroup)rebound).getChildAt(0);assertEquals("Task 01",checkbox.getText().toString());assertFalse(checkbox.isChecked());checkbox.setChecked(true);assertTrue(selected.contains("id0"));assertTrue(selected.contains("id1"));list.setSelectionFromTop(10,-7);}catch(Exception e){throw new RuntimeException(e);}});flow.instrumentation.waitForIdleSync();flow.device.waitForIdle();flow.instrumentation.runOnMainSync(()->{try{ListView list=(ListView)field(ui,"tasks");position[0]=list.getFirstVisiblePosition();position[1]=list.getChildAt(0).getTop();for(int n=0;n<5;n++)invoke(ui,"drawTasks");assertSame(saved[0],list.getAdapter());}catch(Exception e){throw new RuntimeException(e);}});flow.instrumentation.waitForIdleSync();flow.instrumentation.runOnMainSync(()->{try{ListView list=(ListView)field(ui,"tasks");assertEquals(position[0],list.getFirstVisiblePosition());assertEquals(position[1],list.getChildAt(0).getTop());}catch(Exception e){throw new RuntimeException(e);}});}}
 boolean scanServiceRunning(){ActivityManager am=(ActivityManager)flow.context.getSystemService(Context.ACTIVITY_SERVICE);for(ActivityManager.RunningServiceInfo info:am.getRunningServices(100))if(info.service.getClassName().equals(ScanService.class.getName()))return true;return false;}
 @Test public void duplicateScanStartStillStopsServiceAndNotification()throws Exception{try(FakeNas nas=new FakeNas()){flow.setup(nas,List.of());nas.listDelayMillis=80;for(int n=0;n<12;n++){String root="/Movies/Test"+n;nas.folders.add(root);nas.files.put(root+"/Movie.mkv",new byte[]{1});}Intent scan=new Intent(flow.context,ScanService.class).putExtra("library",flow.app.selected().toString());flow.context.startForegroundService(scan);long deadline=System.currentTimeMillis()+10000;while(!flow.app.scanRunning&&System.currentTimeMillis()<deadline)Thread.sleep(20);assertTrue(flow.app.scanRunning);flow.context.startForegroundService(scan);deadline=System.currentTimeMillis()+30000;while((flow.app.scanRunning||scanServiceRunning())&&System.currentTimeMillis()<deadline)Thread.sleep(50);assertFalse(flow.app.scanRunning);assertFalse("Duplicate start must not keep foreground service alive",scanServiceRunning());for(android.service.notification.StatusBarNotification notification:flow.context.getSystemService(NotificationManager.class).getActiveNotifications())assertNotEquals(42,notification.getId());}}
 @Test public void apkRequestsCpuWakeLockButNoWifiStatePermissions()throws Exception{flow.instrumentation=androidx.test.platform.app.InstrumentationRegistry.getInstrumentation();flow.context=flow.instrumentation.getTargetContext();Set<String> permissions=new HashSet<>(Arrays.asList(flow.context.getPackageManager().getPackageInfo(flow.context.getPackageName(),PackageManager.GET_PERMISSIONS).requestedPermissions));assertTrue(permissions.contains("android.permission.WAKE_LOCK"));assertFalse(permissions.contains("android.permission.ACCESS_WIFI_STATE"));assertFalse(permissions.contains("android.permission.CHANGE_WIFI_STATE"));}
 @Test public void fileMultipartPreparesWithoutStartingAndClearsDraftBytes()throws Exception{try(FakeNas nas=new FakeNas()){flow.setup(nas,List.of());DownloadsUi ui=downloads();flow.instrumentation.runOnMainSync(()->{try{invoke(ui,"addition");}catch(Exception e){throw new RuntimeException(e);}});flow.text("Torrentfájl");byte[] data="d4:infod6:lengthi1e4:name7:Fixtureee".getBytes(java.nio.charset.StandardCharsets.US_ASCII);flow.instrumentation.runOnMainSync(()->{flow.app.torrentDraft.bytes=data;flow.app.torrentDraft.filename="fixture.torrent";});flow.text("Hozzáadás");assertTrue(flow.device.wait(Until.hasObject(By.text("release.nfo")),15000));assertEquals(1,nas.torrentUploads);assertArrayEquals(data,nas.uploadedTorrent);assertNull(flow.app.torrentDraft.bytes);assertEquals(0,nas.starts);}}
 @Test public void openingDownloadsDoesNotWaitForBusyModelLock()throws Exception{try(FakeNas nas=new FakeNas()){flow.setup(nas,List.of());MainActivity activity=flow.activity();DownloadStation model=new DownloadStation(flow.app.client,flow.app.store,flow.app.identity);flow.app.downloads=model;java.util.concurrent.CountDownLatch locked=new java.util.concurrent.CountDownLatch(1),release=new java.util.concurrent.CountDownLatch(1),shown=new java.util.concurrent.CountDownLatch(1);Thread holder=new Thread(()->{synchronized(model){locked.countDown();try{release.await();}catch(InterruptedException e){Thread.currentThread().interrupt();}}});holder.setDaemon(true);holder.start();assertTrue(locked.await(2,java.util.concurrent.TimeUnit.SECONDS));boolean responsive;try{flow.app.main.post(()->{activity.downloadsUi=new DownloadsUi(activity);activity.downloadsUi.show();shown.countDown();});responsive=shown.await(3,java.util.concurrent.TimeUnit.SECONDS);}finally{release.countDown();holder.join(3000);}assertTrue("Opening the screen must not wait for a network-owned model monitor",responsive);}}
}
